import path from 'path';
import { createHash } from 'crypto';
import { and, desc, eq, sql } from 'drizzle-orm';
import type {
  VariantHistoryManifest,
  VariantHistorySessionFile,
} from '../../types/variant-history';
import { BUNDLE_SCHEMA } from './migrations';
import {
  openDurableDatabase,
  openReadOnlyDatabase,
  transaction,
  closeDatabase,
} from './database';
import {
  batches,
  presentation,
  project as projects,
  sessions,
  snapshots,
  variants,
} from './schema/bundle';

interface BundleProject {
  id: string;
  name: string;
  workspaceId: string;
}
interface OpenBundleOptions {
  directory: string;
  project: BundleProject;
}
interface SnapshotPointer {
  ref: string;
  commitSha: string;
  treeSha?: string;
}
type Database = Awaited<ReturnType<typeof openDurableDatabase>>;
const PRESENTATION_KEY = 'variants_ui_state';
const PROJECT_SINGLETON = 1;

const identifier = (value: unknown): string =>
  createHash('sha256').update(JSON.stringify(value)).digest('hex');

export class BundleMetadataStore {
  private isClosed = false;
  private constructor(
    private readonly db: Database,
    private readonly project: BundleProject,
  ) {}

  static async open({
    directory,
    project,
  }: OpenBundleOptions): Promise<BundleMetadataStore> {
    const db = await openDurableDatabase({
      databasePath: path.join(directory, 'metadata.sqlite'),
      schema: BUNDLE_SCHEMA,
    });
    try {
      const now = new Date().toISOString();
      db.insert(projects)
        .values({
          singleton: PROJECT_SINGLETON,
          id: project.id,
          name: project.name,
          createdAt: now,
          updatedAt: now,
        })
        .onConflictDoNothing()
        .run();
      if (
        db.select({ id: projects.id }).from(projects).get()?.id !== project.id
      )
        throw new Error('Bundle project identity does not match registration');
      return new BundleMetadataStore(db, project);
    } catch (error) {
      closeDatabase(db);
      throw error;
    }
  }

  static openReadOnly({
    directory,
    project,
  }: OpenBundleOptions): BundleMetadataStore {
    const db = openReadOnlyDatabase({
      databasePath: path.join(directory, 'metadata.sqlite'),
      schemaVersion: 1,
    });
    if (!db) throw new Error('Saved project metadata is unavailable');
    try {
      if (
        db.select({ id: projects.id }).from(projects).get()?.id !== project.id
      )
        throw new Error('Bundle project identity does not match registration');
      return new BundleMetadataStore(db, project);
    } catch (error) {
      closeDatabase(db);
      throw error;
    }
  }

  upsertVariant(manifest: VariantHistoryManifest, artifactPath?: string): void {
    transaction(this.db, () => this.writeVariant(manifest, artifactPath));
  }

  updateVariant(args: {
    sessionId: string;
    variantId: string;
    update: (manifest: VariantHistoryManifest) => void;
  }): boolean {
    return transaction(this.db, () => {
      const manifest = this.getVariant(args.sessionId, args.variantId);
      if (!manifest) return false;
      const before = JSON.stringify(manifest);
      args.update(manifest);
      if (JSON.stringify(manifest) !== before) this.writeVariant(manifest);
      return true;
    });
  }

  artifactPath(sessionId: string, variantId: string): string | null {
    return (
      this.db
        .select({ path: variants.artifactPath })
        .from(variants)
        .where(
          and(
            eq(variants.sessionId, sessionId),
            eq(variants.variantId, variantId),
          ),
        )
        .get()?.path ?? null
    );
  }

  private writeVariant(
    manifest: VariantHistoryManifest,
    artifactPath?: string,
  ): void {
    const {
      sessionId,
      variantId,
      label,
      brief,
      status,
      createdAt,
      statusChangedAt,
      changedFilesCount,
      tree,
      base,
      parent,
      parentVariant,
      ...details
    } = manifest;
    this.db
      .insert(sessions)
      .values({
        id: sessionId,
        initialPrompt: manifest.sessionPrompt,
        projectKind: manifest.projectKind,
        sourceWorkspaceId: this.project.workspaceId,
        createdAt,
        details: {},
      })
      .onConflictDoNothing()
      .run();
    const existing = this.db
      .select({ batchId: variants.batchId })
      .from(variants)
      .where(
        and(
          eq(variants.sessionId, sessionId),
          eq(variants.variantId, variantId),
        ),
      )
      .get();
    const batchId =
      existing?.batchId ??
      identifier([
        sessionId,
        manifest.requestId ?? null,
        manifest.requestId ? null : (manifest.runLabel ?? null),
      ]);
    const batchLabel = manifest.runLabel ?? null;
    this.db
      .insert(batches)
      .values({
        id: batchId,
        sessionId,
        requestId: manifest.requestId ?? null,
        label: batchLabel,
        createdAt,
      })
      .onConflictDoUpdate({
        target: [batches.sessionId, batches.id],
        set: { label: batchLabel },
      })
      .run();
    const metadata = {
      batchId,
      label,
      brief,
      status,
      statusChangedAt,
      changedFilesCount,
      details,
      snapshotId: this.putSnapshot(tree, createdAt),
      baseSnapshotId: this.putSnapshot(base, createdAt),
      parentSnapshotId: this.putSnapshot(parent, createdAt),
      parentSessionId: parentVariant?.sessionId ?? null,
      parentVariantId: parentVariant?.variantId ?? null,
    };
    this.db
      .insert(variants)
      .values({
        sessionId,
        variantId,
        createdAt,
        artifactPath: artifactPath ?? null,
        ...metadata,
      })
      .onConflictDoUpdate({
        target: [variants.sessionId, variants.variantId],
        set: {
          ...metadata,
          ...(artifactPath !== undefined ? { artifactPath } : {}),
        },
      })
      .run();
  }

  getVariant(
    sessionId: string,
    variantId: string,
  ): VariantHistoryManifest | null {
    const row = this.db
      .select()
      .from(variants)
      .where(
        and(
          eq(variants.sessionId, sessionId),
          eq(variants.variantId, variantId),
        ),
      )
      .get();
    return row ? this.decodeVariant(row) : null;
  }

  listVariants(): VariantHistoryManifest[] {
    return this.db
      .select()
      .from(variants)
      .orderBy(desc(variants.createdAt), variants.sessionId, variants.variantId)
      .all()
      .map((row) => this.decodeVariant(row));
  }

  putSession(session: VariantHistorySessionFile): void {
    transaction(this.db, () => {
      this.db
        .insert(sessions)
        .values({
          id: session.sessionId,
          initialPrompt: session.sessionPrompt,
          projectKind: session.projectKind,
          sourceWorkspaceId: this.project.workspaceId,
          createdAt: session.createdAt,
          details: session,
        })
        .onConflictDoUpdate({ target: sessions.id, set: { details: session } })
        .run();
    });
  }

  getSession(sessionId: string): VariantHistorySessionFile | null {
    const row = this.db
      .select()
      .from(sessions)
      .where(eq(sessions.id, sessionId))
      .get();
    if (!row) return null;
    return {
      schemaVersion: 2,
      sessionId,
      sessionPrompt: row.initialPrompt,
      projectKind: row.projectKind,
      createdAt: row.createdAt,
      ...row.details,
    };
  }

  setPresentation(value: unknown): void {
    transaction(this.db, () => {
      const updatedAt = new Date().toISOString();
      const serializedValue = JSON.stringify(value);
      this.db
        .insert(presentation)
        .values({ key: PRESENTATION_KEY, value: serializedValue, updatedAt })
        .onConflictDoUpdate({
          target: presentation.key,
          set: { value: serializedValue, updatedAt },
        })
        .run();
    });
  }

  getPresentation(): unknown {
    const row = this.db
      .select({ value: presentation.value })
      .from(presentation)
      .where(eq(presentation.key, PRESENTATION_KEY))
      .get();
    return row ? JSON.parse(row.value) : null;
  }

  close(): void {
    if (!this.isClosed) {
      closeDatabase(this.db);
      this.isClosed = true;
    }
  }

  private putSnapshot(
    pointer: SnapshotPointer | undefined,
    createdAt: string,
  ): string | null {
    if (!pointer) return null;
    const id = identifier([pointer.ref, pointer.commitSha]);
    this.db
      .insert(snapshots)
      .values({
        id,
        gitRef: pointer.ref,
        commitSha: pointer.commitSha,
        treeSha: pointer.treeSha ?? null,
        createdAt,
      })
      .onConflictDoUpdate({
        target: snapshots.id,
        set: {
          treeSha: sql`coalesce(${snapshots.treeSha}, ${pointer.treeSha ?? null})`,
        },
      })
      .run();
    return id;
  }

  private snapshot(id: string | null): SnapshotPointer | undefined {
    if (id === null) return undefined;
    const row = this.db
      .select()
      .from(snapshots)
      .where(eq(snapshots.id, id))
      .get();
    if (!row) throw new Error('Missing snapshot metadata');
    return {
      ref: row.gitRef,
      commitSha: row.commitSha,
      ...(row.treeSha ? { treeSha: row.treeSha } : {}),
    };
  }

  private decodeVariant(
    row: typeof variants.$inferSelect,
  ): VariantHistoryManifest {
    const tree = this.snapshot(row.snapshotId);
    const base = this.snapshot(row.baseSnapshotId);
    const parent = this.snapshot(row.parentSnapshotId);
    if (tree && !tree.treeSha)
      throw new Error('Missing snapshot tree metadata');
    return {
      ...row.details,
      sessionId: row.sessionId,
      variantId: row.variantId,
      label: row.label,
      brief: row.brief,
      status: row.status,
      createdAt: row.createdAt,
      statusChangedAt: row.statusChangedAt,
      changedFilesCount: row.changedFilesCount,
      ...(tree?.treeSha
        ? {
            tree: {
              ref: tree.ref,
              commitSha: tree.commitSha,
              treeSha: tree.treeSha,
            },
          }
        : {}),
      ...(base ? { base: { ref: base.ref, commitSha: base.commitSha } } : {}),
      ...(parent
        ? { parent: { ref: parent.ref, commitSha: parent.commitSha } }
        : {}),
      ...(row.parentVariantId && row.parentSessionId
        ? {
            parentVariant: {
              sessionId: row.parentSessionId,
              variantId: row.parentVariantId,
            },
          }
        : {}),
    };
  }
}
